package com.novalearn.application.progress;
import com.novalearn.application.child.ChildProfileRepository; import com.novalearn.application.common.ChildNotFoundException; import com.novalearn.application.rewards.RewardsService; import com.novalearn.domain.progress.LessonProgress; import org.junit.jupiter.api.Test; import java.time.Instant; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class ProgressServiceTest { @Test void preserves_higher_score_and_completion(){LessonProgressRepository progress=mock(LessonProgressRepository.class);ChildProfileRepository children=mock(ChildProfileRepository.class);RewardsService rewards=mock(RewardsService.class);UUID parent=UUID.randomUUID(),child=UUID.randomUUID();when(children.belongsToParent(child,parent)).thenReturn(true);when(progress.findByChildIdAndLessonCode(child,"G1-ADD-01")).thenReturn(Optional.of(new LessonProgress(UUID.randomUUID(),child,"G1-ADD-01",80,true,Instant.now())));when(progress.save(any())).thenAnswer(i->i.getArgument(0));ProgressService service=new ProgressService(progress,children,rewards);LessonProgress saved=service.record(parent,child,"G1-ADD-01",60,false);assertThat(saved.score()).isEqualTo(80);assertThat(saved.completed()).isTrue();verifyNoInteractions(rewards);}
 @Test void creates_initial_progress_for_owned_child(){LessonProgressRepository progress=mock(LessonProgressRepository.class);ChildProfileRepository children=mock(ChildProfileRepository.class);RewardsService rewards=mock(RewardsService.class);UUID parent=UUID.randomUUID(),child=UUID.randomUUID();when(children.belongsToParent(child,parent)).thenReturn(true);when(progress.findByChildIdAndLessonCode(child,"G1-ADD-01")).thenReturn(Optional.empty());when(progress.save(any())).thenAnswer(i->i.getArgument(0));ProgressService service=new ProgressService(progress,children,rewards);LessonProgress saved=service.record(parent,child,"G1-ADD-01",75,true);assertThat(saved.score()).isEqualTo(75);assertThat(saved.completed()).isTrue();verify(rewards).recordLessonCompletion(child,75);}
 @Test void doesNotRewardTwiceForReCompletingTheSameLesson(){LessonProgressRepository progress=mock(LessonProgressRepository.class);ChildProfileRepository children=mock(ChildProfileRepository.class);RewardsService rewards=mock(RewardsService.class);UUID parent=UUID.randomUUID(),child=UUID.randomUUID();when(children.belongsToParent(child,parent)).thenReturn(true);when(progress.findByChildIdAndLessonCode(child,"G1-ADD-01")).thenReturn(Optional.of(new LessonProgress(UUID.randomUUID(),child,"G1-ADD-01",80,true,Instant.now())));when(progress.save(any())).thenAnswer(i->i.getArgument(0));ProgressService service=new ProgressService(progress,children,rewards);service.record(parent,child,"G1-ADD-01",90,true);verifyNoInteractions(rewards);}
 @Test void rejects_a_child_outside_parent_account(){LessonProgressRepository progress=mock(LessonProgressRepository.class);ChildProfileRepository children=mock(ChildProfileRepository.class);RewardsService rewards=mock(RewardsService.class);when(children.belongsToParent(any(),any())).thenReturn(false);ProgressService service=new ProgressService(progress,children,rewards);assertThatThrownBy(()->service.list(UUID.randomUUID(),UUID.randomUUID())).isInstanceOf(ChildNotFoundException.class);}}
